import "package:flutter/material.dart"; import "package:intl/intl.dart"; class Utils { static String formatCurrency(double amount) { final formatter = NumberFormat.currency(symbol: "\$", decimalDigits: 0); return formatter.format(amount); } static String formatDate(DateTime date) { final formatter = DateFormat("MMM dd, yyyy"); return formatter.format(date); } static String formatDateTime(DateTime date) { final formatter = DateFormat("MMM dd, yyyy HH:mm"); return formatter.format(date); } static void showSnackBar(BuildContext context, String message, {Color? backgroundColor}) { ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message), backgroundColor: backgroundColor)); } static void showErrorSnackBar(BuildContext context, String message) { showSnackBar(context, message, backgroundColor: Colors.red); } static void showSuccessSnackBar(BuildContext context, String message) { showSnackBar(context, message, backgroundColor: Colors.green); } static Future<bool> showConfirmDialog(BuildContext context, {required String title, required String message, String confirmText = "Yes", String cancelText = "No"}) async { final result = await showDialog<bool>(context: context, builder: (context) => AlertDialog(title: Text(title), content: Text(message), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: Text(cancelText)), ElevatedButton(onPressed: () => Navigator.pop(context, true), child: Text(confirmText))])); return result ?? false; } static String getInitials(String name) { final names = name.split(" "); if (names.length >= 2) { return "\${names[0][0]}\${names[1][0]}".toUpperCase(); } return name.isNotEmpty ? name[0].toUpperCase() : ""; } static Color getStatusColor(String status) { switch (status.toLowerCase()) { case "for sale": return Colors.green; case "for rent": return Colors.orange; case "sold": return Colors.red; default: return Colors.grey; } } }
